// Independent RULE-02 audit probe of the compiled server adapter (synthetic only).
import assert from 'node:assert/strict';
const { createQualificationMatch, assessEngineAdmission } = await import('./packages/engine-adapter/dist/index.js');
let n = 0;
const send = (m, actor, move, input) => m.submit({ actor, expectedRevision: m.status().revision, timestamp: 0, commandId: 'audit-' + ++n, move, input });
const m = createQualificationMatch({ seed: 'audit', players: ['p1', 'p2'] });
assert.equal(send(m, 'p2', 'chooseWhoGoesFirst', { playerId: 'p2' }).accepted, false, 'non-chooser cannot pick first player');
assert.equal(m.status().revision, 0);
assert.equal(send(m, 'p1', 'chooseWhoGoesFirst', { playerId: 'p2' }).accepted, true, 'chooser picks p2');
assert.equal(send(m, 'p1', 'alterHand', { playerId: 'p2', cardsToMulligan: [] }).accepted, false, 'actor cannot act as opponent via playerId');
assert.equal(send(m, 'p2', 'alterHand', { playerId: 'p2', cardsToMulligan: [] }).accepted, true);
assert.equal(send(m, 'p1', 'alterHand', { playerId: 'p1', cardsToMulligan: [] }).accepted, true);
assert.equal(send(m, 'p1', 'passTurn', {}).accepted, false, 'p1 cannot pass p2 turn');
assert.equal(send(m, 'p2', 'forfeitGame', { winnerId: 'p2' }).accepted, false, 'judge move refused under player authority');
for (const bad of [null, [], Object.create(null), { actor: 'p1' }]) assert.throws(() => m.submit(bad));
assert.throws(() => createQualificationMatch({ seed: 'x', players: ['p1', 'p2'], mode: 'collection' }), /options/);
assert.equal(send(m, 'p2', 'concede', {}).accepted, true);
assert.deepEqual(m.status(), { mode: 'qualification', revision: m.status().revision, ended: true, winner: 'p1', rewardEligible: false });
for (const asOf of ['2026-10-15', '2026-10-16', '2026-10-22', '2026-10-23', '2027-01-01']) {
  const r = assessEngineAdmission({ asOf, mode: 'collection', rulesVersion: '2.3.0', sets: ['014'], rewards: false, hiddenState: false });
  assert.equal(r.allowed, false); console.log(asOf, r.rules230Phase, r.set14Phase, r.reasons.join(','));
}
m.dispose();
console.log('PASS independent adapter authority/input/admission probe');
